/**
 * M7 programs on real Postgres (periodised-targets): an M7 scenario profile generated by today's
 * generator and stored with its input as origin, as a build stores it, and its strength sessions
 * logged exactly as planned, every working set at its target RPE, so a week's achieved hard sets
 * are its planned ones.
 */
import { addDays, type IsoDate } from '../../../../src/lib/domain/calendar';
import { CATALOGUE } from '../../../../src/lib/domain/exercises/index';
import {
	buildProgrammingInput,
	catalogueDigest,
	generateProgram,
	GENERATOR_ID
} from '../../../../src/lib/domain/programming';
import type { TrainingProfile } from '../../../../src/lib/domain/profile/types';
import { NON_WORKING_ROLES } from '../../../../src/lib/domain/training/metrics';
import type { Executor } from '../../../../src/lib/server/db';
import { resolveKeys } from '../../../../src/lib/server/services/exercises/index';
import {
	createProgramFromPlan,
	getProgramVersion,
	type StoredSession
} from '../../../../src/lib/server/services/programs/index';
import {
	finishWorkout,
	logSet,
	startWorkout
} from '../../../../src/lib/server/services/training/log';

/** `profile` generated from week 1's Monday `startsOn` and stored with `generator` as its origin. */
export async function storeM7Program(
	db: Executor,
	owner: string,
	profile: TrainingProfile,
	startsOn: IsoDate,
	generator = GENERATOR_ID
) {
	const input = buildProgrammingInput(profile, { catalogue: CATALOGUE });
	const plan = generateProgram(input, { startsOn, firstPlannedDay: startsOn });
	const origin = {
		...{ source: 'rules' as const, generator, digest: catalogueDigest(CATALOGUE, []) },
		snapshot: input as unknown as Record<string, unknown>
	};
	const now = () => new Date(`${addDays(startsOn, -2)}T12:00:00Z`);
	const { programId } = await createProgramFromPlan(owner, plan, origin, { db, now });
	const version = await getProgramVersion(owner, programId, 1, { db });
	return { programId, plan, input, version };
}

/** Log each generated strength session of `sessions` as planned, at noon UTC on its day. */
export async function logAsPlanned(db: Executor, owner: string, sessions: StoredSession[]) {
	const strength = sessions.filter((s) => s.kind === 'strength' && s.source === 'generator');
	const keys = strength.flatMap((s) =>
		s.kind === 'strength' ? s.exercises.map((e) => (e.exercise as { key: string }).key) : []
	);
	const ids = await resolveKeys([...new Set(keys)], { db });
	for (const s of strength) {
		if (s.kind !== 'strength') continue;
		const at = new Date(`${s.date}T12:00:00Z`);
		const clientId = crypto.randomUUID();
		await startWorkout(
			owner,
			{
				...{ clientId, kind: 'strength', discipline: s.discipline, sessionType: s.type },
				...{ title: s.title, plannedSessionId: s.id, startedAt: at.toISOString() }
			},
			{ db }
		);
		let n = 0;
		for (const [position, planned] of s.exercises.entries()) {
			const key = (planned.exercise as { key: string }).key;
			const def = ids.get(key)!;
			// The amount the exercise records, and a weight only where it takes one.
			const amount = { reps: 8, seconds: null, metres: null } as Record<string, number | null>;
			if (def.measure === 'time') Object.assign(amount, { reps: null, seconds: 30 });
			if (def.measure === 'distance') Object.assign(amount, { reps: null, metres: 20 });
			const weight = def.loadType === 'external' ? 40 : null;
			let setIndex = 0;
			for (const line of planned.sets) {
				for (let i = 0; i < line.sets; i++) {
					await logSet(
						owner,
						{
							...{ clientMutationId: crypto.randomUUID(), workoutClientId: clientId },
							...{ exerciseId: def.id, plannedExerciseLineageId: planned.lineage },
							...{ exercisePosition: position + 1, setIndex: ++setIndex },
							...{ weight, unit: 'kg', missedReps: 0, rpe: line.targetRpe },
							reps: amount.reps === null ? null : (line.repsMin ?? amount.reps),
							...{ seconds: amount.seconds, metres: amount.metres },
							...{ isExtra: false, isSkipped: false },
							isWarmup: NON_WORKING_ROLES.includes(line.role),
							performedAt: new Date(at.getTime() + ++n * 60_000).toISOString()
						},
						{ db }
					);
				}
			}
		}
		const finishedAt = new Date(at.getTime() + (n + 5) * 60_000).toISOString();
		const done = { status: 'completed', finishedAt, durationSeconds: (n + 5) * 60, sessionRpe: 7 };
		await finishWorkout(owner, clientId, done, { db });
	}
}
